CREATE COLUMN TABLE "TEST_AP"."OAGP" ("AgentCode" NVARCHAR(32) NOT NULL , "AgentName" NVARCHAR(50) NOT NULL , "Memo" NVARCHAR(50), "Locked" NVARCHAR(1), "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("AgentCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OAGP_AGENT_NAME" ON "TEST_AP"."OAGP" ( "AgentName" ASC )